// Байти шрифтів для resvg
export function interFonts(): Uint8Array[] {
  const dec = (s: string) => Uint8Array.from(atob(s), (ch) => ch.charCodeAt(0));
  return [dec(INTER_400), dec(INTER_600)];
}
